{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Category_Target_vs_Achievement AS WITH Category_Age_Mapping AS ( SELECT DISTINCT TRIM(UPPER(PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(COLLECTION)) AS COLLECTION, CATEGORY_AGE FROM maplemonk.zouk_secondary_sales_Consolidated WHERE CATEGORY_AGE IS NOT NULL ), Category_Level_Target AS ( SELECT TRIM(UPPER(t.Marketplace)) AS Marketplace, TRIM(UPPER(t.Category)) AS PRODUCT_CATEGORY, fsm.Collection, UPPER(fsm.Product_Type) AS Product_Type, DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Target_Date, SAFE_CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF( LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY ) + 1 END AS days_Remaining, EXTRACT( DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)) ) AS no_of_days FROM maplemonk.Zouk_Category_Level_Target t LEFT JOIN ( SELECT * FROM maplemonk.final_sku_master QUALIFY ROW_NUMBER() OVER ( PARTITION BY LOWER(CATEGORY) ORDER BY IFNULL(collection, \'\') DESC ) = 1 ) fsm ON LOWER(fsm.CATEGORY) = LOWER(t.CATEGORY) CROSS JOIN UNNEST( GENERATE_ARRAY( 0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) ) ) AS n QUALIFY ROW_NUMBER() OVER ( PARTITION BY Target_Date, Marketplace, PRODUCT_CATEGORY, Collection ORDER BY Product_Type ) = 1 ), Daily_Achievements AS ( SELECT TRIM(UPPER(s.Marketplace)) AS Marketplace, TRIM(UPPER(s.PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(s.COLLECTION)) AS Collection, TRIM(UPPER(s.product_type)) AS Product_Type, DATE(s.Order_Date) AS Achievement_Date, Category_Launch_Month, SUM( CASE WHEN LOWER(s.marketplace) LIKE ANY (\'myntra%\',\'flipkart\') AND LOWER(s.collection) LIKE \'gifting%\' THEN 0 ELSE IFNULL(s.QUANTITY, 0) END ) + COUNT(DISTINCT CASE WHEN LOWER(s.marketplace) LIKE ANY (\'myntra%\',\'flipkart\') AND LOWER(s.collection) LIKE \'gifting%\' THEN CONCAT( Order_ID, \'_\', TRIM(UPPER(s.Marketplace)), \'_\', TRIM(UPPER(s.Collection)) ) ELSE NULL END ) AS Quantity, SUM(IFNULL(s.Selling_Price, 0)) AS Achievement FROM maplemonk.zouk_secondary_sales_Consolidated s WHERE NOT ( LOWER(IFNULL(ORDER_STATUS,\'\')) LIKE \'%cancel%\' OR LOWER(IFNULL(FINAL_SHIPPING_STATUS,\'\')) LIKE \'%cancel%\' ) AND DATE(s.Order_Date) < CURRENT_DATE(\'Asia/Kolkata\') GROUP BY 1, 2, 3, 4, 5, 6 ), Daily_Spends AS ( SELECT TRIM(UPPER(Marketplace)) AS Marketplace, TRIM(UPPER(PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, TRIM(UPPER(COLLECTION)) AS Collection, TRIM(UPPER( CASE WHEN PRODUCT_TYPE IS NULL OR TRIM(PRODUCT_TYPE) = \'\' THEN COLLECTION ELSE PRODUCT_TYPE END )) AS Product_Type, DATE(Date) AS Spend_Date, SUM(IFNULL(Spend, 0)) AS Spend, SUM(IFNULL(Sales, 0)) AS Sales, SUM(IFNULL(Secondary_Trade_Margin, 0)) AS Secondary_Trade_Margin, SUM(IFNULL(Returns, 0)) AS Returns, SUM(IFNULL(GST, 0)) AS GST, SUM(IFNULL(Secondary_TradeMargin_GST, 0)) AS Secondary_TradeMargin_GST, SUM(IFNULL(COGS, 0)) AS COGS, SUM(IFNULL(BAU_MRP_SALES, 0)) AS BAU_MRP_SALES, SUM(IFNULL(BAU_DISCOUNT, 0)) AS BAU_DISCOUNT, SUM(IFNULL(TRADE_MARGIN, 0)) AS TRADE_MARGIN, SUM(IFNULL(offline_store_cost, 0)) AS Offline_Store_Cost, SUM(IFNULL(store_revenue_share, 0)) AS Store_Revenue_Share, SUM( ( IFNULL(BAU_MRP_SALES, 0) - IFNULL(BAU_DISCOUNT, 0) - IFNULL(Returns, 0) - IFNULL(GST, 0) - IFNULL(TRADE_MARGIN, 0) ) * IFNULL(store_revenue_share, 0) ) AS Store_Revenue_Share_Cost, SUM(IFNULL(LOGISTICS_COST, 0)) AS Logistics_Cost, SUM(IFNULL(CHANNEL_MARGIN, 0)) AS Channel_Margin, SUM(IFNULL(other_performance_spend, 0)) AS Other_Performance_Spend, SUM(IFNULL(brand_spend, 0)) AS Brand_Spend, SUM(IFNULL(Sales, 0)) - SUM(IFNULL(Secondary_Trade_Margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(GST, 0)) + SUM(IFNULL(Secondary_TradeMargin_GST, 0)) AS Net_Sales, SUM(IFNULL(Sales, 0)) - SUM(IFNULL(Secondary_Trade_Margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(GST, 0)) + SUM(IFNULL(Secondary_TradeMargin_GST, 0)) - SUM(IFNULL(COGS, 0)) AS Gross_Margin, SUM(IFNULL(Sales, 0)) - SUM(IFNULL(Secondary_Trade_Margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(GST, 0)) + SUM(IFNULL(Secondary_TradeMargin_GST, 0)) - SUM(IFNULL(COGS, 0)) - SUM(IFNULL(offline_store_cost, 0)) - SUM( ( IFNULL(BAU_MRP_SALES, 0) - IFNULL(BAU_DISCOUNT, 0) - IFNULL(Returns, 0) - IFNULL(GST, 0) - IFNULL(TRADE_MARGIN, 0) ) * IFNULL(store_revenue_share, 0) ) - SUM(IFNULL(LOGISTICS_COST, 0)) - SUM(IFNULL(CHANNEL_MARGIN, 0)) - SUM(IFNULL(Spend, 0)) - SUM(IFNULL(other_performance_spend, 0)) + SUM(IFNULL(brand_spend, 0)) AS Contribution_Margin FROM maplemonk.zouk_secondary_pandl WHERE DATE(Date) < CURRENT_DATE(\'Asia/Kolkata\') GROUP BY 1, 2, 3, 4, 5 ), Combined_Data AS ( SELECT COALESCE( COALESCE(dt.Target_Date, da.Achievement_Date), ds.Spend_Date ) AS Date, COALESCE( COALESCE(dt.Marketplace, da.Marketplace), ds.Marketplace ) AS Marketplace, COALESCE( COALESCE(dt.PRODUCT_CATEGORY, da.PRODUCT_CATEGORY), ds.PRODUCT_CATEGORY ) AS PRODUCT_CATEGORY, COALESCE( COALESCE(dt.Collection, da.Collection), ds.Collection ) AS Collection, COALESCE( COALESCE(dt.Product_Type, da.Product_Type), ds.Product_Type ) AS Product_Type, da.Category_Launch_Month, da.Quantity, dt.Target, dt.days_Remaining, dt.no_of_days, COALESCE(da.Achievement, 0) AS Achievement, COALESCE(ds.Spend, 0) AS Spend, COALESCE(ds.Sales, 0) AS Sales, COALESCE(ds.Secondary_Trade_Margin, 0) AS Secondary_Trade_Margin, COALESCE(ds.Returns, 0) AS Returns, COALESCE(ds.GST, 0) AS GST, COALESCE(ds.Secondary_TradeMargin_GST, 0) AS Secondary_TradeMargin_GST, COALESCE(ds.COGS, 0) AS COGS, COALESCE(ds.BAU_MRP_SALES, 0) AS BAU_MRP_SALES, COALESCE(ds.BAU_DISCOUNT, 0) AS BAU_DISCOUNT, COALESCE(ds.TRADE_MARGIN, 0) AS TRADE_MARGIN, COALESCE(ds.Offline_Store_Cost, 0) AS Offline_Store_Cost, COALESCE(ds.Store_Revenue_Share, 0) AS Store_Revenue_Share, COALESCE(ds.Logistics_Cost, 0) AS Logistics_Cost, COALESCE(ds.Channel_Margin, 0) AS Channel_Margin, COALESCE(ds.Other_Performance_Spend, 0) AS Other_Performance_Spend, COALESCE(ds.Brand_Spend, 0) AS Brand_Spend, COALESCE(ds.Net_Sales, 0) AS Net_Sales, COALESCE(ds.Gross_Margin, 0) AS Gross_Margin, COALESCE(ds.Contribution_Margin, 0) AS Contribution_Margin FROM Category_Level_Target dt FULL OUTER JOIN Daily_Achievements da ON TRIM(dt.Marketplace) = TRIM(da.Marketplace) AND TRIM(dt.PRODUCT_CATEGORY) = TRIM(da.PRODUCT_CATEGORY) AND TRIM(dt.Collection) = TRIM(da.Collection) AND dt.Target_Date = da.Achievement_Date FULL OUTER JOIN Daily_Spends ds ON TRIM(dt.Marketplace) = TRIM(ds.Marketplace) AND TRIM(dt.PRODUCT_CATEGORY) = TRIM(ds.PRODUCT_CATEGORY) AND TRIM(dt.Collection) = TRIM(ds.Collection) AND dt.Target_Date = ds.Spend_Date ), Final_Data AS ( SELECT cd.Date, cd.Marketplace, cd.PRODUCT_CATEGORY, cd.Collection, cd.Product_Type, cd.Category_Launch_Month, cd.Target, cd.Achievement, cd.Spend, cd.Quantity, cd.Sales, cd.Secondary_Trade_Margin, cd.Returns, cd.GST, cd.Secondary_TradeMargin_GST, cd.COGS, cd.BAU_MRP_SALES, cd.BAU_DISCOUNT, cd.TRADE_MARGIN, cd.Offline_Store_Cost, cd.Store_Revenue_Share, cd.Logistics_Cost, cd.Channel_Margin, cd.Other_Performance_Spend, cd.Brand_Spend, cd.Net_Sales, cd.Gross_Margin, cd.Contribution_Margin, cd.days_Remaining, cd.no_of_days, mm.FINAL_MARKETPLACE, mm.Marketplace_Segments, UPPER(mm.Channel) AS Channel, ca.Category_Age, cc.Classification, CASE WHEN mm.Marketplace IS NULL THEN \'Missing in Marketplace Mapping\' ELSE \'Found\' END AS Mapping_Status FROM Combined_Data cd LEFT JOIN ( SELECT * FROM maplemonk.Zouk_db_New_Marketplace_Mapping QUALIFY ROW_NUMBER() OVER ( PARTITION BY LOWER(TRIM(marketplace)) ORDER BY 1 ) = 1 ) mm ON LOWER(TRIM(cd.Marketplace)) = LOWER(TRIM(mm.Marketplace)) LEFT JOIN Category_Age_Mapping ca ON cd.PRODUCT_CATEGORY = ca.PRODUCT_CATEGORY AND cd.Collection = ca.COLLECTION LEFT JOIN maplemonk.zouk_prism_level_it_up cc ON LOWER(TRIM(cd.PRODUCT_CATEGORY)) = LOWER(TRIM(cc.category)) ) SELECT Date, Marketplace, PRODUCT_CATEGORY, Collection, Product_Type, Category_Launch_Month, Target, Achievement, Spend, Quantity, Sales, Secondary_Trade_Margin, Returns, GST, Secondary_TradeMargin_GST, COGS, BAU_MRP_SALES, BAU_DISCOUNT, TRADE_MARGIN, Offline_Store_Cost, Store_Revenue_Share, Logistics_Cost, Channel_Margin, Other_Performance_Spend, Brand_Spend, Net_Sales, Gross_Margin, Contribution_Margin, days_Remaining, no_of_days, FINAL_MARKETPLACE, Marketplace_Segments, Channel, CATEGORY_AGE, Classification FROM Final_Data ORDER BY Date, Marketplace, PRODUCT_CATEGORY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            